  // silently redirects the first session's responses to the second one.
  const createServer = () => {
    const server = new McpServer({
      name: options.name,
      version: "1.0.0",
    }, {
      capabilities: {
        logging: {},
        tools: {
          listChanged: false
        }
      }
    });
    setupCb(server);
    return server;
  };

  const app = express();
  app.use(express.json());

  // Liveness endpoint for the hosting platform's health checks.
  app.get('/healthz', (_req, res) => {
    res.status(200).json({ status: 'ok', sessions: Object.keys(transports).length });
  });

